//! 🔬️ The real scalar heap quotes its actual backing and swap path before mutations.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetirementDemand,work::RetainedWorkLedger};
#[test]fn neutral_heap_original_growth_and_scalar_order_match_independent_reference(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut heap=Heap::<i64>::new(i64::cmp);let mut reference=std::collections::BinaryHeap::new();let mut wallet=super::bounded_tests::wallet();for item in law["values"].as_array().unwrap(){let item=item.as_i64().unwrap();reference.push(std::cmp::Reverse(item));loop{if wallet.turn(1,|work|heap.push_work(item,work)).unwrap(){break;}}}let mut output=Vec::new();loop{match wallet.turn(1,|work|heap.pop_work(work)).unwrap(){HeapWorkPop::Pending=>{},HeapWorkPop::Empty=>break,HeapWorkPop::Ready(value)=>{assert_eq!(Some(std::cmp::Reverse(value)),reference.pop());output.push(value);}}}let expected:Vec<i64>=serde_json::from_value(law["sorted"].clone()).unwrap();assert_eq!(output,expected);assert!(reference.is_empty());wallet.close_owned(heap);}
#[test]fn neutral_boolean_job_keeps_one_original_stock_through_real_geometry_and_fault_custody(){let data:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let rows=super::bounded_tests::rows();let row=&rows[0];let mut job=BooleanJob::new(super::bounded_tests::input(row));let mut wallet=super::bounded_tests::wallet();let mut denied=[false;4];let mut complete=false;for turn in 0..data["maxTurns"].as_u64().unwrap(){let d=job.next_work_demand();for axis in 0..4{let demand=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,_=>d.depth};if denied[axis]||demand==0{continue;}let mut under=wallet.remaining();*match axis{0=>&mut under.maximum_items,1=>&mut under.maximum_copy_bytes,2=>&mut under.maximum_capacity_bytes,_=>&mut under.maximum_depth}=demand-1;let frontier=job.work;let((result,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut no=RetainedWorkLedger::new(under);let result=job.advance(1,&mut no);(result,no.receipt())});assert!(!heap.overflowed);assert!(!result.unwrap().done);assert_eq!(receipt,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(job.work,frontier);assert_eq!(job.last_turn_work(),0);denied[axis]=true;}let before=wallet.remaining();let p=wallet.turn(1,|work|job.advance(1,work)).unwrap();if p.done{complete=true;break;}assert!(wallet.remaining()!=before||job.last_turn_work()>0,"original finite stock exhausted at turn{turn}: {:?}",job.next_work_demand());assert!(job.last_turn_work()<=1);}assert!(complete);assert!(denied.into_iter().all(|axis|axis));let rings=super::bounded_tests::contours(job.result().unwrap());let area=rings.iter().map(|ring|super::bounded_tests::area(ring)).sum::<f64>();assert!((area-row["expected"]["area"].as_f64().unwrap()).abs()<1e-8);let(close,operands,output)=job.into_retirement();let mut close=semio_framework_value::retirement::controlled::ControlledRetirement::retain((close,operands,output));let mut release_denied=false;for _ in 0..data["maxTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break;}let d=close.next_demand(wallet.remaining().maximum_copy_bytes).unwrap();if d.release_bytes>0&&!release_denied{let under=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes-1,maximum_depth:d.depth};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close.step(under).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));release_denied=true;}wallet.close_turn(d,|grant|close.step(grant)).unwrap();}assert!(close.terminal_is_empty());assert!(release_denied);}

#[path="../../../🛤️path/🎟️work/🧪️tests/🦀️.rs"]mod boolean_funding;
#[test]fn source_edges_retain_implicit_endpoints_without_per_edge_index_pages(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let mut wallet=boolean_funding::Wallet::from_grant(RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:s["release"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},law["maxTurns"].as_u64().unwrap()as usize);let rows=super::bounded_tests::rows();let mut job=BooleanJob::new(super::bounded_tests::input(&rows[0]));let mut indexed=false;for _ in 0..law["maxTurns"].as_u64().unwrap(){if job.phase==BooleanPhase::Indexing{indexed=true;break;}wallet.turn(1,|ledger|job.advance(1,ledger)).unwrap();}assert!(indexed);assert!(!job.source.is_empty());assert_eq!(job.parameters,job.source.len()*2);assert!(law["implicitEndpoints"].as_bool().unwrap());assert!(job.source.iter().all(|edge|edge.parameters.is_empty()));wallet.close_owned(job);}
